{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Entecavir, the closest structural analogue sharing the guanine base and carbocyclic nucleoside core, has 100% absolute oral bioavailability in humans, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "A guanine nucleoside prodrug, valomaciclovir stearate, achieved >60% oral bioavailability in humans, supporting favorable oral absorption for guanine-based nucleoside analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Fludarabine, a purine nucleoside analogue, showed approximately 55% systemic availability after oral dosing in patients, supporting F >= 20% for structurally related nucleosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Clofarabine, another purine nucleoside analogue, had 57.5% oral bioavailability in patients, providing additional support for high oral bioavailability in this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Cladribine absolute oral bioavailability was 48% ± 8% in patients, confirming that purine nucleoside analogues commonly exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a carbocyclic guanine nucleoside. The closest analogue entecavir has 100% absolute oral bioavailability in humans, and multiple other purine nucleoside analogues (fludarabine, clofarabine, cladribine, valomaciclovir) show oral bioavailability around 40-70%. Low-F didanosine records are structurally distant and reflect acid lability not shared by the carbocyclic guanine query. Therefore F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the exact query molecule was retrieved.",
    "The exact clinical identity of the query is not explicitly confirmed, so extrapolation relies on close analogues.",
    "Didanosine low-bioavailability data are not transferable because the query lacks the acid-labile dideoxyinosine features responsible for its low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

